/* ============================================================
   Generate js/bundle.js — a classic-script build of the ES modules.

     node tools/build-bundle.mjs

   Why: ES modules are blocked over file://, so opening index.html by
   double-clicking would never boot. index.html loads the modules first
   and falls back to this bundle only if they fail to start.

   RE-RUN THIS AFTER EDITING ANYTHING IN js/. The modules are the source
   of truth; this file is generated output.
   ============================================================ */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ORDER = ['core.js', 'data.js', 'hero.js', 'projects.js', 'booking.js', 'main.js'];

const strip = (src) => src
  // drop `import ... from '...';` (single or multi-line)
  .replace(/^[ \t]*import[\s\S]*?from\s*['"][^'"]+['"];?[ \t]*$/gm, '')
  .replace(/^[ \t]*import\s*['"][^'"]+['"];?[ \t]*$/gm, '')
  // `export const x` -> `const x`, `export function f` -> `function f`
  .replace(/^[ \t]*export\s+(?=(const|let|var|function|class|async)\b)/gm, '')
  .trimEnd();

const parts = ORDER.map((f) => {
  const src = readFileSync(path.join(root, 'js', f), 'utf8');
  return `/* ===== ${f} ===== */\n${strip(src)}\n`;
});

const out = `/* GENERATED by tools/build-bundle.mjs — do not edit.
   Source of truth is js/*.js. Re-run the tool after changing them. */
(function () {
'use strict';
${parts.join('\n')}
})();
`;

const dest = path.join(root, 'js', 'bundle.js');
writeFileSync(dest, out);
console.log(`wrote js/bundle.js (${(out.length / 1024).toFixed(1)} KB) from ${ORDER.length} modules`);
